package com.voiceshift.inference

import com.voiceshift.models.Compatibility
import com.voiceshift.models.ModelFamily
import java.io.File
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Runs the real ONNX Runtime (desktop build of the same Java API) against the small graphs in
 * src/test/resources/models, generated by tools/onnx/make_test_models.py.
 */
class OnnxRuntimeIntegrationTest {

    private fun model(name: String) = File(requireNotNull(javaClass.classLoader!!.getResource("models/$name")).toURI())
    private val validator = OnnxModelValidator(threads = 1)

    @Test
    fun gainModelValidatesAndRuns() {
        val report = validator.validate(model("stream_gain_half.onnx"))
        assertEquals(report.summary, Compatibility.COMPATIBLE, report.compatibility)
        assertEquals(ModelFamily.STREAMING_V1, report.family)
        assertEquals(16000, report.sampleRate)
        assertEquals(1600, report.chunkFrames)
        assertEquals("1.0.0", report.version)
        assertEquals("Apache-2.0", report.license)
        assertNotNull(report.smokeTestRealtimeFactor)

        OrtInferenceSession.open(model("stream_gain_half.onnx"), threads = 1).use { session ->
            val window = FloatArray(1600) { (it % 100) / 100f }
            val out = session.run(window)
            assertEquals(1600, out.size)
            for (i in window.indices) assertEquals(window[i] * 0.5f, out[i], 1e-7f)
        }
    }

    @Test
    fun contextModelReturnsNewestChunk() {
        val report = validator.validate(model("stream_fir_context.onnx"))
        assertEquals(Compatibility.COMPATIBLE, report.compatibility)
        assertEquals(400, report.contextFrames)
        OrtInferenceSession.open(model("stream_fir_context.onnx"), threads = 1).use { session ->
            val window = FloatArray(2000) { if (it == 1000) 1f else 0f }  // impulse inside the chunk
            val out = session.run(window)
            assertEquals(1600, out.size)
            // Impulse at window index 1000 -> chunk index 600; 3-tap kernel [0.25, 0.5, 0.25].
            assertEquals(0.25f, out[599], 1e-6f)
            assertEquals(0.5f, out[600], 1e-6f)
            assertEquals(0.25f, out[601], 1e-6f)
        }
    }

    @Test
    fun modelsWithoutContractAreNotLoadable() {
        val report = validator.validate(model("stream_no_metadata.onnx"))
        assertEquals(Compatibility.UNSUPPORTED, report.compatibility)
        try {
            OrtInferenceSession.open(model("stream_no_metadata.onnx"))
            throw AssertionError("expected failure")
        } catch (e: IllegalArgumentException) {
            assertTrue(e.message!!.contains("stream-v1"))
        }
    }

    @Test
    fun rvcSignatureIsReportedAsUnsupported() {
        val report = validator.validate(model("rvc_like_signature.onnx"))
        assertEquals(ModelFamily.RVC_GENERATOR, report.family)
        assertEquals(Compatibility.UNSUPPORTED, report.compatibility)
        assertEquals(6, report.inputs.size)
    }

    @Test
    fun garbageIsInvalid() {
        val report = validator.validate(model("not_a_model.onnx"))
        assertEquals(Compatibility.INVALID, report.compatibility)
    }

    @Test
    fun workerStreamsThroughRealModelWithTimestamps() {
        OrtInferenceSession.open(model("stream_gain_half.onnx"), threads = 1).use { session ->
            val port = FakePort(chunk = 1600)
            port.feed(FloatArray(3200) { 0.8f })
            val worker = StreamingInferenceWorker(session, port)
            assertTrue(worker.step())
            assertTrue(worker.step())
            assertEquals(listOf(0L, 1600L), port.writtenTimestamps)
            assertEquals(0.4f, port.written.last()[0], 1e-6f)
            assertEquals(2L, worker.stats.value.chunksProcessed)
        }
    }
}
